(() => {
  'use strict';
  const KEY = 'kumbabiz_v1';
  const OWNER_KEY = 'kumbabiz_cloud_owner';
  const BASELINE_KEY = 'kumbabiz_cloud_baseline';
  const fresh = () => ({ business: { name: 'My Business', phone: '', address: '' }, products: [], customers: [], sales: [], language: 'en', createdAt: new Date().toISOString() });
  let db = load();
  let page = 'dashboard';
  let query = '';
  let salesFilter = 'all';
  let cart = [];
  let authMode = 'login';
  let syncTimer = null;
  const cloud = { client: null, user: null, status: 'local', pending: null, error: '' };
  const app = document.getElementById('app');
  const t = (en, fr) => db.language === 'fr' ? fr : en;
  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money = n => new Intl.NumberFormat(db.language === 'fr' ? 'fr-FR' : 'en-US', { maximumFractionDigits: 0 }).format(Number(n || 0)) + ' FCFA';
  const dateFmt = value => value ? new Intl.DateTimeFormat(db.language === 'fr' ? 'fr-FR' : 'en-GB', { day:'2-digit', month:'short', year:'numeric' }).format(new Date(value)) : '—';
  const initials = name => (name || '?').trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
  function load(){ try { const x=JSON.parse(localStorage.getItem(KEY)); return x && Array.isArray(x.products) ? {...fresh(),...x,business:{...fresh().business,...(x.business||{})}} : fresh(); } catch { return fresh(); } }
  function save(){ localStorage.setItem(KEY, JSON.stringify(db)); if(cloud.user && !cloud.pending && cloud.status!=='loading') queueCloudSave(); }
  function toast(msg){ const el=document.querySelector('.toast'); if(!el)return; el.textContent=msg; el.classList.add('show'); setTimeout(()=>el.classList.remove('show'),2500); }
  function syncLabel(){const labels={local:t('Local only','Stockage local'),signedout:t('Local only','Stockage local'),loading:t('Connecting…','Connexion…'),syncing:t('Syncing…','Synchronisation…'),synced:t('Cloud synced','Cloud synchronisé'),offline:t('Offline — saved here','Hors ligne — enregistré ici'),setup:t('Setup needed','Configuration requise'),conflict:t('Choose data to sync','Choisir les données'),error:t('Sync issue','Problème de sync')};return `<span class="sync-dot ${cloud.status==='synced'?'ok':cloud.status==='error'||cloud.status==='setup'?'warn':''}"></span>${labels[cloud.status]||labels.local}`;}
  function refreshSyncLabel(){const el=document.getElementById('cloud-indicator');if(el)el.innerHTML=syncLabel();}
  function hasLocalData(x=db){return !!(x.products?.length||x.customers?.length||x.sales?.length||x.business?.name&&x.business.name!=='My Business'||x.business?.phone||x.business?.address);}
  function stableStringify(value){if(Array.isArray(value))return '['+value.map(stableStringify).join(',')+']';if(value&&typeof value==='object')return '{'+Object.keys(value).sort().map(k=>JSON.stringify(k)+':'+stableStringify(value[k])).join(',')+'}';return JSON.stringify(value);}
  function normalizeWorkspace(x){const base=fresh();return {...base,...(x||{}),business:{...base.business,...(x?.business||{})},products:Array.isArray(x?.products)?x.products:[],customers:Array.isArray(x?.customers)?x.customers:[],sales:Array.isArray(x?.sales)?x.sales:[]};}
  function initCloud(){const cfg=window.KUMBABIZ_SUPABASE;if(!window.supabase?.createClient||!cfg?.url||!cfg?.publishableKey){cloud.status='setup';cloud.error='Supabase settings are missing.';refreshSyncLabel();return;}try{cloud.client=window.supabase.createClient(cfg.url,cfg.publishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});cloud.status='signedout';cloud.client.auth.onAuthStateChange((_event,session)=>{setTimeout(()=>handleSession(session),0);});cloud.client.auth.getSession().then(({data,error})=>{if(error)throw error;handleSession(data.session);}).catch(()=>{cloud.status='offline';cloud.error=t('Could not reach Supabase. Your local records are safe.','Connexion à Supabase impossible. Vos données locales sont conservées.');refreshSyncLabel();});}catch{cloud.status='setup';cloud.error='Supabase client could not start.';refreshSyncLabel();}}
  async function handleSession(session){cloud.user=session?.user||null;cloud.pending=null;if(!cloud.user){cloud.status=cloud.client?'signedout':'setup';cloud.error='';refreshSyncLabel();if(page==='account')render();return;}cloud.status='loading';refreshSyncLabel();try{const {data,error}=await cloud.client.from('user_workspaces').select('payload,updated_at').eq('owner_id',cloud.user.id).maybeSingle();if(error)throw error;if(!data){if(hasLocalData()){cloud.pending={kind:'new',payload:null};cloud.status='conflict';}else{db=normalizeWorkspace(fresh());localStorage.setItem(KEY,JSON.stringify(db));const ok=await pushCloud();if(!ok)cloud.status='error';}}else{const remote=normalizeWorkspace(data.payload);const localHas=hasLocalData();const owner=localStorage.getItem(OWNER_KEY);const baseline=localStorage.getItem(BASELINE_KEY);const localText=stableStringify(db),remoteText=stableStringify(remote);if(localHas&&localText!==remoteText){if(owner===cloud.user.id&&baseline){const baseText=stableStringify(JSON.parse(baseline));if(localText===baseText){db=remote;localStorage.setItem(KEY,JSON.stringify(db));localStorage.setItem(BASELINE_KEY,stableStringify(db));cloud.status='synced';}else if(remoteText===baseText){cloud.pending={kind:'existing',payload:remote};cloud.status='conflict';}else{cloud.pending={kind:'existing',payload:remote};cloud.status='conflict';}}else{cloud.pending={kind:'existing',payload:remote};cloud.status='conflict';}}else{db=remote;localStorage.setItem(KEY,JSON.stringify(db));localStorage.setItem(OWNER_KEY,cloud.user.id);localStorage.setItem(BASELINE_KEY,stableStringify(db));cloud.status='synced';}}cloud.error='';}catch(err){cloud.status='setup';cloud.error='The private workspace table is not ready yet. Run supabase-schema.sql in your Supabase project SQL Editor.';}refreshSyncLabel();render();}
  function queueCloudSave(){if(!cloud.client||!cloud.user||cloud.pending)return;cloud.status='syncing';refreshSyncLabel();clearTimeout(syncTimer);syncTimer=setTimeout(()=>pushCloud(),700);}
  async function pushCloud(){if(!cloud.client||!cloud.user||cloud.pending)return false;cloud.status='syncing';refreshSyncLabel();try{const payload=normalizeWorkspace(JSON.parse(JSON.stringify(db)));const {error}=await cloud.client.from('user_workspaces').upsert({owner_id:cloud.user.id,payload,updated_at:new Date().toISOString()},{onConflict:'owner_id'});if(error)throw error;localStorage.setItem(KEY,JSON.stringify(payload));localStorage.setItem(OWNER_KEY,cloud.user.id);localStorage.setItem(BASELINE_KEY,stableStringify(payload));cloud.status='synced';cloud.error='';refreshSyncLabel();if(page==='account')render();return true;}catch{cloud.status='error';cloud.error=t('Cloud sync failed. Your latest changes remain saved on this device; try again when online.','Échec de la synchronisation. Vos changements restent enregistrés sur cet appareil ; réessayez lorsque vous serez connecté.');refreshSyncLabel();if(page==='account')render();return false;}}
  async function resolveCloud(choice){if(!cloud.user||!cloud.pending)return;const pending=cloud.pending;if(choice==='cloud'){if(!confirm(pending.kind==='new'?t('Start a fresh cloud workspace? Your records on this device will be replaced. Download a backup first if needed.','Créer un espace cloud vide ? Les données de cet appareil seront remplacées. Téléchargez une sauvegarde si nécessaire.'):t('Use the cloud copy on this device? Local-only changes will be replaced. Download a backup first if needed.','Utiliser la copie cloud sur cet appareil ? Les changements locaux seront remplacés. Téléchargez une sauvegarde si nécessaire.')))return;db=pending.payload?normalizeWorkspace(pending.payload):normalizeWorkspace(fresh());localStorage.setItem(KEY,JSON.stringify(db));cloud.pending=null;cloud.status='syncing';if(pending.kind==='new'){await pushCloud();}else{localStorage.setItem(OWNER_KEY,cloud.user.id);localStorage.setItem(BASELINE_KEY,stableStringify(db));cloud.status='synced';render();}}else{if(!confirm(t('Upload this device’s records to your account? If a cloud workspace already exists, it will be replaced.','Téléverser les données de cet appareil vers votre compte ? Un espace cloud existant sera remplacé.')))return;cloud.pending=null;await pushCloud();}}
  async function submitAuth(){if(!cloud.client){toast(t('Cloud setup is not ready yet.','La configuration cloud n’est pas encore prête.'));return;}const email=document.getElementById('auth-email')?.value.trim(),password=document.getElementById('auth-password')?.value;if(!email||!password){toast(t('Enter your email and password.','Entrez votre e-mail et votre mot de passe.'));return;}cloud.status='loading';refreshSyncLabel();try{if(authMode==='signup'){const {data,error}=await cloud.client.auth.signUp({email,password,options:{emailRedirectTo:location.origin+location.pathname}});if(error)throw error;if(data.session)await handleSession(data.session);else{toast(t('Account created. Check your email to confirm, then sign in here.','Compte créé. Confirmez votre e-mail, puis connectez-vous ici.'));authMode='login';render();}}else{const {data,error}=await cloud.client.auth.signInWithPassword({email,password});if(error)throw error;if(data.session)await handleSession(data.session);} }catch(err){cloud.status='signedout';refreshSyncLabel();toast(err?.message||t('Could not sign in. Check your details and try again.','Connexion impossible. Vérifiez vos informations et réessayez.'));}}
  async function resetAuthPassword(){const email=document.getElementById('auth-email')?.value.trim();if(!email){toast(t('Enter your email first.','Entrez d’abord votre e-mail.'));return;}try{const {error}=await cloud.client.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname});if(error)throw error;toast(t('Password reset instructions sent if the account exists.','Instructions de réinitialisation envoyées si le compte existe.'));}catch{toast(t('Could not send a reset email right now.','Impossible d’envoyer l’e-mail de réinitialisation pour le moment.'));}}
  function signOut(){if(!cloud.client)return;cloud.client.auth.signOut().then(()=>{cloud.user=null;cloud.pending=null;cloud.status='signedout';page='account';render();});}
  function accountPage(){if(!cloud.client)return `<div class="welcome"><div><h1>${t('Account & cloud sync','Compte et synchronisation')}</h1><p>${t('Cloud service is not available yet.','Le service cloud n’est pas encore disponible.')}</p></div></div><div class="card form-card"><h3>${t('Local app remains available','L’application locale reste disponible')}</h3><p>${esc(cloud.error||t('Check the Supabase configuration and try again.','Vérifiez la configuration Supabase et réessayez.'))}</p></div>`;if(cloud.user){const pending=cloud.pending;return `<div class="welcome"><div><h1>${t('Account & cloud sync','Compte et synchronisation')}</h1><p>${t('Your KumbaBiz records can sync with this Supabase account.','Vos données KumbaBiz peuvent se synchroniser avec ce compte Supabase.')}</p></div><button class="btn secondary" data-action="sign-out">${t('Sign out','Déconnexion')}</button></div><div class="grid settings-grid"><div class="card form-card"><h3>${t('Signed in','Connecté')}</h3><p>${t('Account','Compte')}: <b>${esc(cloud.user.email||'')}</b></p><div class="info-box">${cloud.status==='synced'?t('Cloud workspace is synced. Your records are stored under your account and protected by row-level access rules.','Espace cloud synchronisé. Vos données sont rattachées à votre compte et protégées par des règles d’accès par utilisateur.'):cloud.status==='syncing'?t('Sync in progress…','Synchronisation en cours…'):cloud.status==='conflict'?t('Choose which copy to keep before syncing. Download a backup first if you are unsure.','Choisissez la copie à conserver avant la synchronisation. Téléchargez une sauvegarde en cas de doute.'):esc(cloud.error||t('Waiting for cloud sync.','En attente de la synchronisation cloud.'))}</div>${pending?`<div class="conflict-box"><b>${pending.kind==='new'?t('No cloud workspace exists yet.','Aucun espace cloud n’existe encore.'):t('Cloud and device both have records.','Le cloud et cet appareil contiennent des données.')}</b><p>${pending.kind==='new'?t('Choose whether to upload this device’s data or start with an empty cloud workspace.','Choisissez de téléverser les données de cet appareil ou de commencer avec un espace cloud vide.'):t('Choose the cloud copy or upload this device’s records instead.','Choisissez la copie cloud ou téléversez plutôt les données de cet appareil.')}</p><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn soft" data-action="choose-cloud">${pending.kind==='new'?t('Start empty in cloud','Commencer vide dans le cloud'):t('Use cloud copy','Utiliser la copie cloud')}</button><button class="btn" data-action="choose-local">${t('Upload this device','Téléverser cet appareil')}</button></div></div>`:`<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:16px"><button class="btn secondary" data-action="sync-now">↻ ${t('Sync now','Synchroniser')}</button><button class="btn secondary" data-action="export-json">⇩ ${t('Download backup','Télécharger une sauvegarde')}</button></div>`}</div><div class="card form-card"><h3>${t('Data protection','Protection des données')}</h3><p>${t('Only the signed-in account can read or change its workspace. This app syncs one workspace per account.','Seul le compte connecté peut lire ou modifier son espace. Cette application synchronise un espace par compte.')}</p><div class="info-box">${t('Use the same account on another device to load your workspace. Avoid editing the same account on multiple devices at once; the latest synced copy can replace earlier changes. Keep regular backups.','Connectez-vous avec le même compte sur un autre appareil pour retrouver vos données. Évitez de modifier le même compte sur plusieurs appareils à la fois : la dernière copie synchronisée peut remplacer les changements précédents. Faites des sauvegardes régulières.')}</div>${cloud.error?`<p class="modal-error">${esc(cloud.error)}</p>`:''}</div></div>`;}return `<div class="welcome"><div><h1>${t('Account & cloud sync','Compte et synchronisation')}</h1><p>${t('Sign in to back up and sync your business records across devices.','Connectez-vous pour sauvegarder et synchroniser les données de votre entreprise sur plusieurs appareils.')}</p></div></div><div class="grid settings-grid"><div class="card form-card"><h3>${authMode==='signup'?t('Create your KumbaBiz account','Créer votre compte KumbaBiz'):t('Sign in to KumbaBiz','Se connecter à KumbaBiz')}</h3><p>${t('This is your app account, separate from your Supabase dashboard login.','C’est votre compte pour l’application, séparé de votre connexion au tableau de bord Supabase.')}</p><div class="field"><label>${t('Email','E-mail')}</label><input id="auth-email" type="email" autocomplete="email" required placeholder="name@example.com"/></div><div class="field"><label>${t('Password','Mot de passe')}</label><input id="auth-password" type="password" autocomplete="${authMode==='signup'?'new-password':'current-password'}" minlength="8" required/></div><button class="btn" data-action="auth-submit">${authMode==='signup'?t('Create account','Créer le compte'):t('Sign in','Se connecter')}</button><div style="display:flex;gap:14px;flex-wrap:wrap;margin-top:15px"><button class="text-link" data-action="toggle-auth">${authMode==='signup'?t('Already have an account? Sign in','Déjà un compte ? Se connecter'):t('Need an account? Sign up','Besoin d’un compte ? S’inscrire')}</button>${authMode==='login'?`<button class="text-link" data-action="reset-password">${t('Forgot password?','Mot de passe oublié ?')}</button>`:''}</div><div class="info-box">${t('Your password is sent only to Supabase Auth. KumbaBiz never stores it in your business records.','Votre mot de passe est transmis uniquement à Supabase Auth. KumbaBiz ne le stocke jamais dans vos données métier.')}</div></div><div class="card form-card"><h3>${t('What cloud sync changes','Ce que la synchronisation apporte')}</h3><p>${t('Your workspace can be loaded on another device after you sign in. The local-only app still works if you sign out or lose connection.','Votre espace peut être chargé sur un autre appareil après connexion. L’application locale reste utilisable si vous vous déconnectez ou perdez la connexion.')}</p><ul style="padding-left:18px;color:var(--muted);font-size:12px;line-height:1.9"><li>${t('One private workspace per account','Un espace privé par compte')}</li><li>${t('Access protected by Supabase Row Level Security','Accès protégé par Row Level Security de Supabase')}</li><li>${t('Backups can still be downloaded as JSON','Les sauvegardes JSON restent disponibles')}</li></ul></div></div>`;}
  function updateCloudUI(){refreshSyncLabel();if(page==='account')render();}
  function dataCount(){return db.products.length+db.customers.length+db.sales.length;}
  
  function totalSales(){ return db.sales.reduce((s,x)=>s+Number(x.total||0),0); }
  function totalCollected(){ return db.sales.reduce((s,x)=>s+Number(x.paid||0),0); }
  function totalOwed(){ return db.sales.reduce((s,x)=>s+Math.max(0,Number(x.total||0)-Number(x.paid||0)),0); }
  function navItems(){ return [['dashboard','▦',t('Overview','Vue générale')],['sales','↗',t('Sales','Ventes')],['inventory','▤',t('Inventory','Inventaire')],['customers','♙',t('Customers','Clients')],['account','◉',t('Account & sync','Compte et sync')],['reports','▥',t('Reports','Rapports')],['settings','⚙',t('Settings','Paramètres')]]; }
  function render(){ document.documentElement.lang=db.language; app.innerHTML=`<div class="shell">${sidebar()}<main class="main"><header class="topbar"><div class="top-left"><button class="mobile-menu" data-action="toggle-menu" aria-label="Menu">☰</button><div class="page-heading">${navItems().find(x=>x[0]===page)?.[2]||''}</div></div><div class="top-actions"><span class="sync-pill" id="cloud-indicator">${syncLabel()}</span><span class="today">${new Intl.DateTimeFormat(db.language==='fr'?'fr-FR':'en-GB',{weekday:'short',day:'numeric',month:'short',year:'numeric'}).format(new Date())}</span><select class="lang-select" id="language"><option value="en" ${db.language==='en'?'selected':''}>English</option><option value="fr" ${db.language==='fr'?'selected':''}>Français</option></select></div></header><section class="content">${pageContent()}</section></main><nav class="mobile-nav">${navItems().slice(0,5).map(([id,ic,label])=>`<button data-page="${id}" class="${page===id?'active':''}"><span>${ic}</span><span>${label}</span></button>`).join('')}</nav><div class="toast"></div><div id="modal-root"></div></div>`; }
  function sidebar(){return `<aside class="sidebar" id="sidebar"><div class="brand"><div class="brandmark">K</div><div class="brandname">Kumba<span>Biz</span></div></div><div class="business-switch"><div class="biz-avatar">${esc(initials(db.business.name).slice(0,1))}</div><div class="biz-info"><strong>${esc(db.business.name)}</strong><small>${cloud.user?esc(cloud.user.email):t('Cameroon business','Entreprise au Cameroun')}</small></div><span class="muted">⌄</span></div><div class="nav-label">${t('WORKSPACE','ESPACE DE TRAVAIL')}</div><nav class="nav">${navItems().map(([id,ic,label])=>`<button data-page="${id}" class="${page===id?'active':''}"><span class="nav-icon">${ic}</span>${label}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note"><strong>${t('Your data stays yours','Vos données restent les vôtres')}</strong>${cloud.user?t('Cloud sync is on for this account.','La synchronisation cloud est activée pour ce compte.'):t('Records stay on this device until you sign in and enable cloud sync.','Les données restent sur cet appareil jusqu’à votre connexion et activation du cloud.')}</div><div class="profile"><div class="profile-avatar">${esc(initials(db.business.name).slice(0,1))}</div><span>${esc(db.business.name)}</span></div></div></aside>`; }
  function pageContent(){ if(page==='dashboard')return dashboard(); if(page==='sales')return salesPage(); if(page==='inventory')return inventoryPage(); if(page==='customers')return customersPage(); if(page==='reports')return reportsPage(); if(page==='account')return accountPage(); return settingsPage(); }
  function greeting(){const h=new Date().getHours(); return h<12?t('Good morning','Bonjour'):h<17?t('Good afternoon','Bon après-midi'):t('Good evening','Bonsoir');}
  function dashboard(){const low=db.products.filter(p=>Number(p.stock)<=Number(p.lowAt));const recent=[...db.sales].sort((a,b)=>new Date(b.date)-new Date(a.date)).slice(0,6);return `<div class="welcome"><div><h1>${greeting()}, ${esc(db.business.name)} 👋</h1><p>${t('Here is how your business is doing today.','Voici le résumé de votre activité.')}</p></div><button class="btn" data-action="new-sale">＋ ${t('Record a sale','Enregistrer une vente')}</button></div><div class="grid stats">${stat(t('Total sales','Ventes totales'),money(totalSales()),t('All recorded sales','Toutes les ventes enregistrées'),'↗')}${stat(t('Money collected','Montant encaissé'),money(totalCollected()),t('Payments received','Paiements reçus'),'₣')}${stat(t('Customers owing','Reste à encaisser'),money(totalOwed()),t('Unpaid balances','Soldes impayés'),'◷')}${stat(t('Products in stock','Produits en stock'),db.products.reduce((s,p)=>s+Number(p.stock||0),0).toLocaleString(),`${db.products.length} ${t('products','produits')}`,'▤')}</div><div class="grid dash-grid"><div class="card panel"><div class="panel-head"><div><div class="panel-title">${t('Recent sales','Ventes récentes')}</div><div class="panel-subtitle">${t('Latest transactions recorded','Dernières transactions enregistrées')}</div></div><button class="text-link" data-page="sales">${t('View all','Tout voir')} →</button></div>${recent.length?`<div class="table-wrap"><table class="table"><thead><tr><th>${t('Customer','Client')}</th><th>${t('Date','Date')}</th><th>${t('Total','Total')}</th><th>${t('Payment','Paiement')}</th></tr></thead><tbody>${recent.map(s=>`<tr><td>${esc(customerName(s.customerId)||t('Walk-in customer','Client de passage'))}</td><td class="muted">${dateFmt(s.date)}</td><td class="amount">${money(s.total)}</td><td>${paymentStatus(s)}</td></tr>`).join('')}</tbody></table></div>`:emptyState('↗',t('No sales recorded yet','Aucune vente enregistrée'),t('Record your first sale to start seeing your business activity here.','Enregistrez votre première vente pour suivre votre activité ici.'),t('Record first sale','Enregistrer une vente'),'new-sale')}</div><div class="grid" style="gap:16px"><div class="card panel"><div class="panel-head"><div><div class="panel-title">${t('Quick actions','Actions rapides')}</div><div class="panel-subtitle">${t('Get things done faster','Gagnez du temps')}</div></div></div><div class="quick-grid"><button class="quick-action" data-action="new-sale"><span class="quick-icon">＋</span><b>${t('New sale','Nouvelle vente')}</b><small>${t('Record a transaction','Enregistrer une transaction')}</small></button><button class="quick-action" data-action="add-product"><span class="quick-icon">▤</span><b>${t('Add product','Ajouter un produit')}</b><small>${t('Update your stock','Mettre à jour le stock')}</small></button><button class="quick-action" data-action="add-customer"><span class="quick-icon">♙</span><b>${t('Add customer','Ajouter un client')}</b><small>${t('Save customer details','Enregistrer un client')}</small></button><button class="quick-action" data-action="export-json"><span class="quick-icon">⇩</span><b>${t('Backup data','Sauvegarder')}</b><small>${t('Download a copy','Télécharger une copie')}</small></button></div></div><div class="card panel"><div class="panel-head"><div><div class="panel-title">${t('Low stock','Stock bas')}</div><div class="panel-subtitle">${t('Products to check','Produits à vérifier')}</div></div><button class="text-link" data-page="inventory">${t('Inventory','Inventaire')} →</button></div>${low.length?`<div class="stock-list">${low.slice(0,5).map(p=>`<div class="stock-row"><div><div class="stock-name">${esc(p.name)}</div><div class="stock-meta">${t('Reorder at','Alerte à')} ${p.lowAt} ${t('units','unités')}</div></div><span class="status ${Number(p.stock)===0?'danger':'warning'}">${p.stock} ${t('left','restant')}</span></div>`).join('')}</div>`:`<div class="empty" style="padding:14px 8px"><b>${t('All clear','Tout est en ordre')}</b><p>${t('Add products and get a heads-up when stock runs low.','Ajoutez des produits pour être averti lorsque le stock baisse.')}</p></div>`}</div></div></div>`;}
  function stat(title,value,caption,icon){return `<div class="card stat-card"><div class="stat-top"><span>${title}</span><span class="stat-icon">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-caption">${caption}</div></div>`;}
  function emptyState(icon,title,desc,button,action){return `<div class="empty"><div class="empty-icon">${icon}</div><b>${title}</b><p>${desc}</p><button class="btn small" data-action="${action}">＋ ${button}</button></div>`;}
  function customerName(id){return db.customers.find(c=>c.id===id)?.name||'';}
  function paymentStatus(s){const due=Number(s.total)-Number(s.paid);return due<=0?`<span class="status">● ${t('Paid','Payé')}</span>`:`<span class="status warning">● ${money(due)} ${t('due','dû')}</span>`;}
  function filtered(items,fields){if(!query.trim())return items;const q=query.toLowerCase();return items.filter(x=>fields.some(k=>String(x[k]||'').toLowerCase().includes(q)));}
  function toolbar(placeholder,button,action,extra=''){return `<div class="page-toolbar"><div class="toolbar-left"><input class="search" id="search" placeholder="⌕ ${placeholder}" value="${esc(query)}"/>${extra}</div><div class="toolbar-right"><button class="btn" data-action="${action}">＋ ${button}</button></div></div>`;}
  function salesPage(){let items=[...db.sales].sort((a,b)=>new Date(b.date)-new Date(a.date));if(salesFilter==='paid')items=items.filter(s=>Number(s.paid)>=Number(s.total));if(salesFilter==='owing')items=items.filter(s=>Number(s.paid)<Number(s.total));items=items.filter(s=>!query||`${customerName(s.customerId)} ${s.id}`.toLowerCase().includes(query.toLowerCase()));return `${toolbar(t('Search sales or customer...','Rechercher une vente ou un client...'),t('Record sale','Enregistrer une vente'),'new-sale',`<div class="tabs"><button data-filter="all" class="${salesFilter==='all'?'active':''}">${t('All','Toutes')}</button><button data-filter="paid" class="${salesFilter==='paid'?'active':''}">${t('Paid','Payées')}</button><button data-filter="owing" class="${salesFilter==='owing'?'active':''}">${t('Owing','Impayées')}</button></div>`)}<div class="card panel">${items.length?`<div class="table-wrap"><table class="table"><thead><tr><th>${t('Reference','Référence')}</th><th>${t('Customer','Client')}</th><th>${t('Date','Date')}</th><th>${t('Items','Articles')}</th><th>${t('Total','Total')}</th><th>${t('Paid','Payé')}</th><th>${t('Status','Statut')}</th><th>${t('Actions','Actions')}</th></tr></thead><tbody>${items.map(s=>`<tr><td class="muted">${esc(s.id.slice(-7).toUpperCase())}</td><td>${esc(customerName(s.customerId)||t('Walk-in','Passage'))}</td><td class="muted">${dateFmt(s.date)}</td><td>${s.items.reduce((a,x)=>a+Number(x.qty),0)}</td><td class="amount">${money(s.total)}</td><td>${money(s.paid)}</td><td>${paymentStatus(s)}</td><td><div class="row-actions"><button class="icon-btn" title="${t('Print invoice','Imprimer la facture')}" data-action="invoice" data-id="${s.id}">▧</button><button class="icon-btn" title="${t('Delete sale','Supprimer la vente')}" data-action="delete-sale" data-id="${s.id}">×</button></div></td></tr>`).join('')}</tbody></table></div>`:emptyState('↗',t('No sales found','Aucune vente trouvée'),query?t('Try a different search.','Essayez une autre recherche.'):t('Your recorded sales will appear here.','Vos ventes enregistrées apparaîtront ici.'),t('Record a sale','Enregistrer une vente'),'new-sale')}</div>`;}
  function inventoryPage(){const items=filtered([...db.products].sort((a,b)=>a.name.localeCompare(b.name)),['name','category','sku']);return `${toolbar(t('Search products...','Rechercher des produits...'),t('Add product','Ajouter un produit'),'add-product')}<div class="card panel">${items.length?`<div class="table-wrap"><table class="table"><thead><tr><th>${t('Product','Produit')}</th><th>${t('Category','Catégorie')}</th><th>${t('Selling price','Prix de vente')}</th><th>${t('Stock','Stock')}</th><th>${t('Stock value','Valeur du stock')}</th><th>${t('Actions','Actions')}</th></tr></thead><tbody>${items.map(p=>`<tr><td><div class="product-cell"><div class="product-mark">▤</div><div><b>${esc(p.name)}</b><div class="muted" style="font-size:10px">${esc(p.sku||'')}</div></div></div></td><td class="muted">${esc(p.category||'—')}</td><td class="amount">${money(p.price)}</td><td><span class="status ${Number(p.stock)<=Number(p.lowAt)?(Number(p.stock)===0?'danger':'warning'):''}">${p.stock}</span></td><td>${money(Number(p.stock)*Number(p.cost||0))}</td><td><div class="row-actions"><button class="icon-btn" data-action="restock" data-id="${p.id}" title="${t('Restock','Réapprovisionner')}">＋</button><button class="icon-btn" data-action="edit-product" data-id="${p.id}" title="${t('Edit','Modifier')}">✎</button><button class="icon-btn" data-action="delete-product" data-id="${p.id}" title="${t('Delete','Supprimer')}">×</button></div></td></tr>`).join('')}</tbody></table></div>`:emptyState('▤',t('No products yet','Aucun produit'),t('Add products to manage stock and record sales accurately.','Ajoutez vos produits pour gérer le stock et enregistrer les ventes.'),t('Add first product','Ajouter un produit'),'add-product')}</div>`;}
  function customerBalance(c){return db.sales.filter(s=>s.customerId===c.id).reduce((sum,s)=>sum+Math.max(0,Number(s.total)-Number(s.paid)),0);}
  function customersPage(){const items=filtered([...db.customers].sort((a,b)=>a.name.localeCompare(b.name)),['name','phone','email']);return `${toolbar(t('Search customers...','Rechercher des clients...'),t('Add customer','Ajouter un client'),'add-customer')}<div class="card panel">${items.length?`<div class="table-wrap"><table class="table"><thead><tr><th>${t('Customer','Client')}</th><th>${t('Phone','Téléphone')}</th><th>${t('Sales','Ventes')}</th><th>${t('Outstanding','Reste dû')}</th><th>${t('Actions','Actions')}</th></tr></thead><tbody>${items.map(c=>{const owing=customerBalance(c),count=db.sales.filter(s=>s.customerId===c.id).length;return `<tr><td><div class="customer-cell"><div class="mini-avatar">${esc(initials(c.name))}</div><div><b>${esc(c.name)}</b><div class="muted" style="font-size:10px">${esc(c.email||'')}</div></div></div></td><td>${esc(c.phone||'—')}</td><td>${count}</td><td class="amount" style="color:${owing?'var(--orange)':'inherit'}">${money(owing)}</td><td><div class="row-actions">${owing&&c.phone?`<button class="icon-btn" data-action="remind" data-id="${c.id}" title="${t('WhatsApp reminder','Rappel WhatsApp')}">◉</button>`:''}<button class="icon-btn" data-action="edit-customer" data-id="${c.id}" title="${t('Edit','Modifier')}">✎</button><button class="icon-btn" data-action="delete-customer" data-id="${c.id}" title="${t('Delete','Supprimer')}">×</button></div></td></tr>`}).join('')}</tbody></table></div>`:emptyState('♙',t('No customers yet','Aucun client'),t('Save customer details to track their purchases and balances.','Enregistrez vos clients pour suivre leurs achats et soldes.'),t('Add first customer','Ajouter un client'),'add-customer')}</div>`;}
  function reportsPage(){const daily=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));d.setHours(0,0,0,0);const next=new Date(d);next.setDate(next.getDate()+1);return {d,total:db.sales.filter(s=>new Date(s.date)>=d&&new Date(s.date)<next).reduce((a,s)=>a+Number(s.total),0)}});const max=Math.max(1,...daily.map(x=>x.total));return `<div class="welcome"><div><h1>${t('Reports','Rapports')}</h1><p>${t('A clear picture of your sales and stock.','Une vue claire de vos ventes et de votre stock.')}</p></div><button class="btn secondary" data-action="export-csv">⇩ ${t('Export sales CSV','Exporter les ventes CSV')}</button></div><div class="notice">${t('Reports are calculated from the records saved on this device. Keep a backup before changing devices.','Les rapports sont calculés à partir des données enregistrées sur cet appareil. Faites une sauvegarde avant de changer d’appareil.')}</div><div class="grid report-metrics">${reportMetric(t('Recorded sales','Ventes enregistrées'),money(totalSales()))}${reportMetric(t('Collected','Encaissé'),money(totalCollected()))}${reportMetric(t('Still owed','Reste à encaisser'),money(totalOwed()))}</div><div class="card panel" style="margin-bottom:16px"><div class="panel-head"><div><div class="panel-title">${t('Sales — last 7 days','Ventes — 7 derniers jours')}</div><div class="panel-subtitle">${t('Based on transaction date','Selon la date des transactions')}</div></div></div><div class="chart-bars">${daily.map((x,i)=>`<div class="chart-col"><div class="bar ${i===6?'current':''}" style="height:${Math.max(3,x.total/max*100)}%" title="${money(x.total)}"></div><span class="bar-label">${new Intl.DateTimeFormat(db.language==='fr'?'fr-FR':'en-GB',{weekday:'short'}).format(x.d)}</span></div>`).join('')}</div></div><div class="card panel"><div class="panel-head"><div><div class="panel-title">${t('Inventory summary','Résumé du stock')}</div></div></div><div class="table-wrap"><table class="table"><thead><tr><th>${t('Products tracked','Produits suivis')}</th><th>${t('Units in stock','Unités en stock')}</th><th>${t('Low-stock items','Articles en stock bas')}</th><th>${t('Estimated cost value','Valeur au prix de revient')}</th></tr></thead><tbody><tr><td>${db.products.length}</td><td>${db.products.reduce((a,p)=>a+Number(p.stock),0)}</td><td>${db.products.filter(p=>Number(p.stock)<=Number(p.lowAt)).length}</td><td class="amount">${money(db.products.reduce((a,p)=>a+Number(p.stock)*Number(p.cost||0),0))}</td></tr></tbody></table></div></div>`;}
  function reportMetric(label,value){return `<div class="card report-metric"><small>${label}</small><strong>${value}</strong></div>`;}
  function settingsPage(){return `<div class="welcome"><div><h1>${t('Settings','Paramètres')}</h1><p>${t('Set up your business and manage your data.','Configurez votre entreprise et gérez vos données.')}</p></div></div><div class="grid settings-grid"><div class="card form-card"><h3>${t('Business profile','Profil de l’entreprise')}</h3><p>${t('These details appear on your business records and printable receipts.','Ces informations apparaissent sur vos documents et reçus.')}</p><form id="business-form"><div class="field"><label>${t('Business name','Nom de l’entreprise')} *</label><input name="name" required maxlength="70" value="${esc(db.business.name)}" placeholder="${t('e.g. Ashu Fashion','ex. Ashu Fashion')}"/></div><div class="field-grid"><div class="field"><label>${t('Phone number','Téléphone')}</label><input name="phone" maxlength="25" value="${esc(db.business.phone)}" placeholder="+237 6..."/></div><div class="field"><label>${t('Currency','Devise')}</label><input value="XAF — FCFA" disabled/></div></div><div class="field"><label>${t('Business address','Adresse de l’entreprise')}</label><input name="address" maxlength="120" value="${esc(db.business.address)}" placeholder="${t('Town or neighbourhood','Ville ou quartier')}"/></div><button class="btn">${t('Save business profile','Enregistrer le profil')}</button></form></div><div class="grid" style="gap:16px"><div class="card form-card"><h3>${t('Data & backups','Données et sauvegardes')}</h3><p>${cloud.user?t('Your records sync to your signed-in account. Export a backup for an extra copy.','Vos données se synchronisent avec le compte connecté. Exportez une sauvegarde pour conserver une copie.'):t('Your records are stored in this browser on this device. Sign in under Account & sync to use cloud backup.','Vos données sont stockées dans ce navigateur sur cet appareil. Connectez-vous dans Compte et sync pour activer la sauvegarde cloud.')}</p><div style="display:grid;gap:9px"><button class="btn secondary" data-action="export-json">⇩ ${t('Download backup','Télécharger une sauvegarde')}</button><label class="btn secondary" for="import-file">⇧ ${t('Restore from backup','Restaurer une sauvegarde')}<input id="import-file" type="file" accept="application/json,.json" class="hidden"/></label></div><div class="info-box">${cloud.user?t('Cloud sync is enabled for this account. Avoid editing the same account on multiple devices at once and keep regular backups.','La synchronisation cloud est activée pour ce compte. Évitez de modifier le même compte sur plusieurs appareils en même temps et faites des sauvegardes régulières.'):t('Sign in under Account & sync to back up this workspace to the cloud.','Connectez-vous dans Compte et sync pour sauvegarder cet espace dans le cloud.')}</div></div><div class="card form-card"><h3>${t('Privacy and control','Confidentialité et contrôle')}</h3><p>${cloud.user?t('Your records are sent to Supabase for account sync and protected by row-level access rules. WhatsApp reminders still open for you to review and send.','Vos données sont envoyées à Supabase pour la synchronisation et protégées par des règles d’accès. Les rappels WhatsApp s’ouvrent toujours pour que vous les vérifiiez et les envoyiez.'):t('While signed out, records stay in this browser. WhatsApp reminders open for you to review and send.','Lorsque vous êtes déconnecté, les données restent dans ce navigateur. Les rappels WhatsApp s’ouvrent pour que vous les vérifiiez et les envoyiez.')}</p><button class="btn danger" data-action="reset-data">${t('Clear all local data','Effacer toutes les données locales')}</button></div></div></div>`;}
  function showModal(title,body,foot='',wide=false){document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop" data-action="backdrop-close"><div class="modal ${wide?'wide':''}" role="dialog" aria-modal="true"><div class="modal-head"><h2>${title}</h2><button class="close" data-action="close-modal" aria-label="Close">×</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}</div></div>`;}
  function closeModal(){document.getElementById('modal-root').innerHTML='';cart=[];}
  function productForm(p={}){const editing=!!p.id;showModal(editing?t('Edit product','Modifier le produit'):t('Add a product','Ajouter un produit'),`<form id="product-form"><div class="field"><label>${t('Product name','Nom du produit')} *</label><input name="name" required maxlength="80" value="${esc(p.name||'')}" placeholder="${t('e.g. Rice, shirts, hair cream','ex. Riz, chemises, crème capillaire')}"/></div><div class="field-grid"><div class="field"><label>${t('Selling price (FCFA)','Prix de vente (FCFA)')} *</label><input type="number" name="price" min="0" step="1" required value="${p.price??''}"/></div><div class="field"><label>${t('Cost price (FCFA)','Prix de revient (FCFA)')}</label><input type="number" name="cost" min="0" step="1" value="${p.cost??''}"/></div></div><div class="field-grid"><div class="field"><label>${t('Quantity in stock','Quantité en stock')} *</label><input type="number" name="stock" min="0" step="1" required value="${p.stock??0}"/></div><div class="field"><label>${t('Low-stock alert at','Alerte stock bas à')}</label><input type="number" name="lowAt" min="0" step="1" value="${p.lowAt??5}"/></div></div><div class="field-grid"><div class="field"><label>${t('Category','Catégorie')}</label><input name="category" maxlength="40" value="${esc(p.category||'')}"/></div><div class="field"><label>${t('SKU / code (optional)','SKU / code (facultatif)')}</label><input name="sku" maxlength="30" value="${esc(p.sku||'')}"/></div></div><div class="modal-error" id="modal-error"></div></form>`,`<button class="btn secondary" data-action="close-modal">${t('Cancel','Annuler')}</button><button class="btn" data-action="save-product" data-id="${p.id||''}">${editing?t('Save changes','Enregistrer'):t('Add product','Ajouter le produit')}</button>`);}
  function customerForm(c={}){const editing=!!c.id;showModal(editing?t('Edit customer','Modifier le client'):t('Add a customer','Ajouter un client'),`<form id="customer-form"><div class="field"><label>${t('Customer name','Nom du client')} *</label><input name="name" required maxlength="70" value="${esc(c.name||'')}"/></div><div class="field-grid"><div class="field"><label>${t('Phone number','Téléphone')}</label><input name="phone" maxlength="25" value="${esc(c.phone||'')}" placeholder="+237 6..."/></div><div class="field"><label>${t('Email (optional)','E-mail (facultatif)')}</label><input type="email" name="email" maxlength="100" value="${esc(c.email||'')}"/></div></div><div class="field"><label>${t('Notes','Notes')}</label><input name="notes" maxlength="160" value="${esc(c.notes||'')}"/></div><div class="modal-error" id="modal-error"></div></form>`,`<button class="btn secondary" data-action="close-modal">${t('Cancel','Annuler')}</button><button class="btn" data-action="save-customer" data-id="${c.id||''}">${editing?t('Save changes','Enregistrer'):t('Add customer','Ajouter le client')}</button>`);}
  function newSale(){cart=[];if(!db.products.length){toast(t('Add at least one product before recording a sale.','Ajoutez au moins un produit avant d’enregistrer une vente.'));page='inventory';render();return;}showModal(t('Record a sale','Enregistrer une vente'),`<form id="sale-form"><div class="field"><label>${t('Customer','Client')}</label><select name="customerId"><option value="">${t('Walk-in customer / no account','Client de passage / aucun compte')}</option>${db.customers.map(c=>`<option value="${c.id}">${esc(c.name)}${c.phone?' — '+esc(c.phone):''}</option>`).join('')}</select><span class="field-help">${t('No customer selected? The sale will still be recorded.','Aucun client sélectionné ? La vente sera quand même enregistrée.')}</span></div><div class="field"><label>${t('Add products to this sale','Ajouter des produits à la vente')}</label><div class="cart-heading"><span>${t('Product','Produit')}</span><span>${t('Qty','Qté')}</span><span>${t('Price','Prix')}</span><span></span></div><div id="cart-rows"></div><button type="button" class="btn secondary small" data-action="cart-add">＋ ${t('Add another item','Ajouter un article')}</button></div><div class="field-grid"><div class="field"><label>${t('Amount paid now (FCFA)','Montant payé maintenant (FCFA)')} *</label><input type="number" id="sale-paid" name="paid" min="0" step="1" required value="0"/></div><div class="field"><label>${t('Sale date','Date de vente')}</label><input type="date" name="date" value="${new Date().toISOString().slice(0,10)}"/></div></div><div class="cart-summary"><span>${t('Total','Total')}</span><strong id="cart-total">0 FCFA</strong></div><div class="modal-error" id="modal-error"></div></form>`,`<button class="btn secondary" data-action="close-modal">${t('Cancel','Annuler')}</button><button class="btn" data-action="save-sale">${t('Save sale','Enregistrer la vente')}</button>`,true);addCartRow();}
  function addCartRow(){const wrap=document.getElementById('cart-rows');if(!wrap)return;const id='row-'+Math.random().toString(36).slice(2,8);const row=document.createElement('div');row.className='cart-row';row.dataset.row=id;row.innerHTML=`<select class="cart-product"><option value="">${t('Choose product','Choisir un produit')}</option>${db.products.map(p=>`<option value="${p.id}" data-price="${p.price}" data-stock="${p.stock}">${esc(p.name)} (${p.stock} ${t('in stock','en stock')})</option>`).join('')}</select><input type="number" class="cart-qty" min="1" step="1" value="1" aria-label="${t('Quantity','Quantité')}"/><span class="line-total">0</span><button type="button" class="icon-btn" data-action="cart-remove" data-row="${id}">×</button>`;wrap.appendChild(row);}
  function updateCart(){let total=0;document.querySelectorAll('.cart-row').forEach(r=>{const opt=r.querySelector('.cart-product')?.selectedOptions[0],qty=Number(r.querySelector('.cart-qty')?.value||0),price=Number(opt?.dataset.price||0),available=Number(opt?.dataset.stock||0);const line=qty*price;total+=line;const label=r.querySelector('.line-total');if(label)label.textContent=money(line);if(qty>available&&opt?.value)r.querySelector('.cart-qty').setCustomValidity(t('Quantity exceeds stock','La quantité dépasse le stock'));else r.querySelector('.cart-qty')?.setCustomValidity('');});const el=document.getElementById('cart-total');if(el)el.textContent=money(total);const paid=document.getElementById('sale-paid');if(paid){paid.max=total;paid.placeholder=`0 – ${total}`;}}
  function saveProduct(id){const form=document.getElementById('product-form');if(!form.reportValidity())return;const fd=new FormData(form),data={name:fd.get('name').trim(),price:Number(fd.get('price')),cost:Number(fd.get('cost')||0),stock:Number(fd.get('stock')),lowAt:Number(fd.get('lowAt')||0),category:fd.get('category').trim(),sku:fd.get('sku').trim()};if(data.price<0||data.stock<0){document.getElementById('modal-error').textContent=t('Prices and stock cannot be negative.','Les prix et le stock ne peuvent pas être négatifs.');return;}if(id){Object.assign(db.products.find(p=>p.id===id),data);}else db.products.push({id:crypto.randomUUID(),...data,createdAt:new Date().toISOString()});save();closeModal();render();toast(t('Product saved.','Produit enregistré.'));}
  function saveCustomer(id){const form=document.getElementById('customer-form');if(!form.reportValidity())return;const fd=new FormData(form),data={name:fd.get('name').trim(),phone:fd.get('phone').trim(),email:fd.get('email').trim(),notes:fd.get('notes').trim()};if(id)Object.assign(db.customers.find(c=>c.id===id),data);else db.customers.push({id:crypto.randomUUID(),...data,createdAt:new Date().toISOString()});save();closeModal();render();toast(t('Customer saved.','Client enregistré.'));}
  function saveSale(){const form=document.getElementById('sale-form');if(!form.reportValidity())return;const lines=[...document.querySelectorAll('.cart-row')].map(r=>{const opt=r.querySelector('.cart-product').selectedOptions[0];return {productId:opt?.value,name:opt?.textContent?.split(' (')[0],qty:Number(r.querySelector('.cart-qty').value),price:Number(opt?.dataset.price||0),available:Number(opt?.dataset.stock||0)}}).filter(x=>x.productId);if(!lines.length){document.getElementById('modal-error').textContent=t('Add at least one product.','Ajoutez au moins un produit.');return;}if(lines.some(x=>x.qty>x.available)){document.getElementById('modal-error').textContent=t('A quantity is greater than the available stock.','Une quantité dépasse le stock disponible.');return;}const total=lines.reduce((a,x)=>a+x.qty*x.price,0),paid=Number(new FormData(form).get('paid'));if(paid>total||paid<0){document.getElementById('modal-error').textContent=t('Amount paid must be between zero and the sale total.','Le montant payé doit être compris entre zéro et le total.');return;}for(const l of lines){const p=db.products.find(p=>p.id===l.productId);p.stock=Number(p.stock)-l.qty;}const date=new FormData(form).get('date');db.sales.push({id:crypto.randomUUID(),customerId:new FormData(form).get('customerId')||null,items:lines.map(({available,...x})=>x),total,paid,date:new Date((date||new Date().toISOString().slice(0,10))+'T12:00:00').toISOString(),createdAt:new Date().toISOString()});save();closeModal();page='sales';query='';render();toast(t('Sale recorded and stock updated.','Vente enregistrée et stock mis à jour.'));}
  function restock(id){const p=db.products.find(x=>x.id===id);const qty=Number(prompt(t(`How many units of ${p.name} are you adding?`,`Combien d’unités de ${p.name} ajoutez-vous ?`),'1'));if(!Number.isInteger(qty)||qty<=0)return;p.stock=Number(p.stock)+qty;save();render();toast(t('Stock updated.','Stock mis à jour.'));}
  function deleteSale(id){if(!confirm(t('Delete this sale? Its items will be returned to stock.','Supprimer cette vente ? Les articles seront remis en stock.')))return;const s=db.sales.find(x=>x.id===id);if(s)s.items.forEach(i=>{const p=db.products.find(x=>x.id===i.productId);if(p)p.stock=Number(p.stock)+Number(i.qty);});db.sales=db.sales.filter(x=>x.id!==id);save();render();toast(t('Sale deleted and stock restored.','Vente supprimée et stock rétabli.'));}
  function deleteProduct(id){const p=db.products.find(x=>x.id===id);if(!p)return;if(!confirm(t(`Delete ${p.name} from inventory? Past sale records will remain.`,`Supprimer ${p.name} de l’inventaire ? Les ventes passées seront conservées.`)))return;db.products=db.products.filter(x=>x.id!==id);save();render();toast(t('Product deleted.','Produit supprimé.'));}
  function deleteCustomer(id){const c=db.customers.find(x=>x.id===id);if(!c)return;if(db.sales.some(s=>s.customerId===id)){toast(t('This customer has sales. Keep the record to preserve history.','Ce client a des ventes. Gardez sa fiche pour préserver l’historique.'));return;}if(!confirm(t(`Delete ${c.name}?`,`Supprimer ${c.name} ?`)))return;db.customers=db.customers.filter(x=>x.id!==id);save();render();}
  function remind(id){const c=db.customers.find(x=>x.id===id),bal=customerBalance(c);let phone=(c.phone||'').replace(/[^\d]/g,'');if(phone.startsWith('0'))phone='237'+phone.slice(1);if(phone&&!phone.startsWith('237'))phone='237'+phone;const msg=t(`Hello ${c.name}, this is a friendly reminder that your outstanding balance with ${db.business.name} is ${money(bal)}. Please let us know when you can make the payment. Thank you.`,`Bonjour ${c.name}, petit rappel : votre solde restant chez ${db.business.name} est de ${money(bal)}. Merci de nous indiquer quand vous pourrez effectuer le paiement.`);window.open(`https://wa.me/${phone}?text=${encodeURIComponent(msg)}`,'_blank','noopener');}
  function invoice(id){const s=db.sales.find(x=>x.id===id);if(!s)return;const c=db.customers.find(x=>x.id===s.customerId),due=Number(s.total)-Number(s.paid);const w=window.open('','_blank');if(!w){toast(t('Allow pop-ups to print the invoice.','Autorisez les fenêtres contextuelles pour imprimer la facture.'));return;}w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${t('Receipt','Reçu')} ${esc(s.id.slice(-7))}</title><style>body{font:15px Arial,sans-serif;color:#182c28;max-width:700px;margin:40px auto;padding:0 20px}h1{color:#0f766e;margin-bottom:4px}.muted{color:#687672}.head{display:flex;justify-content:space-between;border-bottom:2px solid #0f766e;padding-bottom:20px}.items{width:100%;border-collapse:collapse;margin:30px 0}.items th,.items td{text-align:left;padding:12px 8px;border-bottom:1px solid #e5ece8}.right{text-align:right!important}.total{text-align:right;font-size:18px;font-weight:bold}.thanks{margin-top:50px;border-top:1px solid #ddd;padding-top:15px;color:#687672}@media print{button{display:none}}</style></head><body><div class="head"><div><h1>${esc(db.business.name)}</h1><div class="muted">${esc(db.business.phone||'')}${db.business.address?' · '+esc(db.business.address):''}</div></div><div style="text-align:right"><h2>${t('SALES RECEIPT','REÇU DE VENTE')}</h2><div>${t('Reference','Référence')}: ${esc(s.id.slice(-7).toUpperCase())}</div><div>${dateFmt(s.date)}</div></div></div><p><b>${t('Customer','Client')}:</b> ${esc(c?.name||t('Walk-in customer','Client de passage'))}${c?.phone?' · '+esc(c.phone):''}</p><table class="items"><thead><tr><th>${t('Item','Article')}</th><th>${t('Qty','Qté')}</th><th>${t('Unit price','Prix unitaire')}</th><th class="right">${t('Amount','Montant')}</th></tr></thead><tbody>${s.items.map(i=>`<tr><td>${esc(i.name)}</td><td>${i.qty}</td><td>${money(i.price)}</td><td class="right">${money(i.qty*i.price)}</td></tr>`).join('')}</tbody></table><div class="total">${t('Total','Total')}: ${money(s.total)}<br>${t('Paid','Payé')}: ${money(s.paid)}<br>${t('Balance due','Solde dû')}: ${money(due)}</div><p class="thanks">${t('Thank you for your business.','Merci pour votre confiance.')}</p><button onclick="window.print()">${t('Print receipt','Imprimer le reçu')}</button><script>window.onload=()=>window.print()</script></body></html>`);w.document.close();}
  function exportJSON(){const blob=new Blob([JSON.stringify({...db,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});download(blob,`kumbabiz-backup-${new Date().toISOString().slice(0,10)}.json`);toast(t('Backup downloaded.','Sauvegarde téléchargée.'));}
  function exportCSV(){const rows=[[t('Sale reference','Référence'),t('Date','Date'),t('Customer','Client'),t('Items','Articles'),t('Total XAF','Total FCFA'),t('Paid XAF','Payé FCFA'),t('Balance XAF','Solde FCFA')],...db.sales.map(s=>[s.id,dateFmt(s.date),customerName(s.customerId)||t('Walk-in','Passage'),s.items.map(x=>`${x.name} × ${x.qty}`).join(' / '),s.total,s.paid,Math.max(0,s.total-s.paid)])];const csv='\uFEFF'+rows.map(r=>r.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');download(new Blob([csv],{type:'text/csv;charset=utf-8'}),`kumbabiz-sales-${new Date().toISOString().slice(0,10)}.csv`);toast(t('Sales report downloaded.','Rapport des ventes téléchargé.'));}
  function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500);}
  function importBackup(file){const reader=new FileReader();reader.onload=()=>{try{const x=JSON.parse(reader.result);if(!Array.isArray(x.products)||!Array.isArray(x.customers)||!Array.isArray(x.sales))throw Error('invalid');if(!confirm(t('Restore this backup? It will replace the data currently in this browser.','Restaurer cette sauvegarde ? Elle remplacera les données actuellement dans ce navigateur.')))return;db={...fresh(),...x,business:{...fresh().business,...(x.business||{})}};save();render();toast(t('Backup restored.','Sauvegarde restaurée.'));}catch{toast(t('That backup file could not be read.','Impossible de lire ce fichier de sauvegarde.'));}};reader.readAsText(file);}
  app.addEventListener('click',e=>{const pageBtn=e.target.closest('[data-page]');if(pageBtn){page=pageBtn.dataset.page;query='';document.getElementById('sidebar')?.classList.remove('open');render();return;}const f=e.target.closest('[data-filter]');if(f){salesFilter=f.dataset.filter;render();return;}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;switch(a){case'toggle-menu':document.getElementById('sidebar')?.classList.toggle('open');break;case'new-sale':newSale();break;case'add-product':productForm();break;case'edit-product':productForm(db.products.find(x=>x.id===id));break;case'add-customer':customerForm();break;case'edit-customer':customerForm(db.customers.find(x=>x.id===id));break;case'save-product':saveProduct(id);break;case'save-customer':saveCustomer(id);break;case'save-sale':saveSale();break;case'cart-add':addCartRow();break;case'cart-remove':document.querySelector(`[data-row="${b.dataset.row}"]`)?.remove();updateCart();break;case'restock':restock(id);break;case'delete-sale':deleteSale(id);break;case'delete-product':deleteProduct(id);break;case'delete-customer':deleteCustomer(id);break;case'remind':remind(id);break;case'invoice':invoice(id);break;case'export-json':exportJSON();break;case'export-csv':exportCSV();break;case'close-modal':closeModal();break;case'backdrop-close':if(e.target===b)closeModal();break;case'reset-data':if(confirm(cloud.user?t('This permanently clears KumbaBiz data on this device and in your cloud account. Download a backup first. Continue?','Cette action efface définitivement les données KumbaBiz sur cet appareil et dans votre compte cloud. Téléchargez d’abord une sauvegarde. Continuer ?'):t('This permanently clears all KumbaBiz data saved in this browser. Download a backup first if needed. Continue?','Cette action efface définitivement toutes les données KumbaBiz de ce navigateur. Téléchargez d’abord une sauvegarde si besoin. Continuer ?'))){db=fresh();save();page='dashboard';render();toast(t('Data cleared.','Données effacées.'));}break;case'auth-submit':submitAuth();break;case'toggle-auth':authMode=authMode==='login'?'signup':'login';render();break;case'reset-password':resetAuthPassword();break;case'sign-out':signOut();break;case'sync-now':pushCloud();break;case'choose-cloud':resolveCloud('cloud');break;case'choose-local':resolveCloud('local');break;}}
  );
  app.addEventListener('input',e=>{if(e.target.id==='search'){const start=e.target.selectionStart;query=e.target.value;const pos=e.target.selectionStart;render();const next=document.getElementById('search');next?.focus();next?.setSelectionRange(pos,pos);}if(e.target.classList.contains('cart-qty'))updateCart();});
  app.addEventListener('change',e=>{if(e.target.id==='language'){db.language=e.target.value;save();render();}if(e.target.id==='import-file'&&e.target.files?.[0])importBackup(e.target.files[0]);if(e.target.classList.contains('cart-product'))updateCart();});
  app.addEventListener('submit',e=>{if(e.target.id==='business-form'){e.preventDefault();const fd=new FormData(e.target);db.business={...db.business,name:fd.get('name').trim(),phone:fd.get('phone').trim(),address:fd.get('address').trim()};save();render();toast(t('Business profile saved.','Profil enregistré.'));}});
  app.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
  window.addEventListener('online',()=>{if(cloud.user&&!cloud.pending)pushCloud();});
  render();
  initCloud();
})();
